const reelSlots = ["07:30", "18:30", "22:20", "07:30"];
function kstNow() {
  const now = new Date();
  const parts = new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Seoul", year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(now);
  const y = parts.find(p => p.type === "year").value;
  const m = parts.find(p => p.type === "month").value;
  const d = parts.find(p => p.type === "day").value;
  return `${y}-${m}-${d}`;
}
function extractFirstUrl(value) {
  if (!value) return "";
  if (Array.isArray(value) && value.length) return String(value[0] || "").trim();
  const text = String(value || "").trim();
  if (!text) return "";
  if (text.startsWith("[")) {
    try {
      const parsed = JSON.parse(text);
      if (Array.isArray(parsed) && parsed.length) return String(parsed[0] || "").trim();
    } catch (e) {}
  }
  return text;
}
function isValidPublicMp4(url) {
  const value = String(url || "").trim();
  if (!value || !/^https:\/\//i.test(value)) return false;
  let parsed;
  try { parsed = new URL(value); } catch (e) { return false; }
  const host = String(parsed.hostname || "").toLowerCase();
  if (!host || host === "example.com" || host.endsWith(".example.com")) return false;
  if (/^(localhost|127\.|10\.|192\.168\.|172\.(1[6-9]|2\d|3[0-1])\.)/.test(host)) return false;
  return /\.mp4($|\?)/i.test(parsed.pathname + parsed.search);
}
function pickReelVideoUrl(row) {
  const candidates = [
    row.video_url,
    row.reel_video_url,
    row.reel_video,
    row.reel_mp4_url,
    row.public_video_url,
    row.video?.url,
    extractFirstUrl(row.video_urls_json),
    extractFirstUrl(row.video_urls),
  ];
  for (const c of candidates) {
    const v = String(c || "").trim();
    if (v) return v;
  }
  return "";
}
const today = kstNow();
const reels = items.filter(i => String(i.json.content_type || "").toLowerCase() === "reel").sort((a, b) => Number(b.json.score || 0) - Number(a.json.score || 0));
const feeds = items.filter(i => String(i.json.content_type || "").toLowerCase() === "feed").sort((a, b) => Number(b.json.score || 0) - Number(a.json.score || 0));
const normalized = [];

reels.forEach((item, idx) => {
  const row = item.json;
  const slot = reelSlots[idx] || "07:30";
  const subtitles = Array.isArray(row.scene_json) ? row.scene_json.map(s => s.caption).filter(Boolean).join(" | ") : String(row.reel_script || row.body || row.final_title || "");
  const imageUrl = String(row.cover_url || row.image_url || row.photo || extractFirstUrl(row.image_urls_json) || extractFirstUrl(row.image_urls) || "").trim();
  const videoUrl = pickReelVideoUrl(row);
  if (!isValidPublicMp4(videoUrl)) return;

  const required = [row.final_title, row.body, subtitles, row.source_link, row.hashtags, slot, videoUrl];
  if (required.some(v => !String(v || "").trim())) return;

  const contentId = String(row.content_key || row.content_id || "").trim();
  normalized.push({
    json: {
      ...row,
      content_id: contentId,
      platform: "reel",
      title: row.final_title,
      body: row.body,
      subtitles,
      source_url: row.source_link,
      hashtags: row.hashtags,
      image_url: imageUrl || String(row.cover_url || row.image_url || "").trim(),
      video_url: videoUrl,
      time_slot: `${today} ${slot}`,
      status: "draft",
      telegram_message_id: "",
      content_key: contentId
    }
  });
});

feeds.forEach((item) => {
  const row = item.json;
  const subtitles = String(row.body || row.final_title || "");
  const imageUrl = String(row.cover_url || row.image_url || row.photo || extractFirstUrl(row.image_urls_json) || extractFirstUrl(row.image_urls) || row.data?.[0]?.url || "").trim();
  const videoUrl = String(row.video_url || row.reel_video_url || row.cover_url || row.photo || imageUrl || "").trim();
  const required = [row.final_title, row.body, subtitles, row.source_link, row.hashtags, imageUrl, videoUrl];
  if (required.some(v => !String(v || "").trim())) return;
  const contentId = String(row.content_key || row.content_id || "").trim();
  normalized.push({ json: { ...row, content_id: contentId, platform: "feed", title: row.final_title, body: row.body, subtitles, source_url: row.source_link, hashtags: row.hashtags, image_url: imageUrl || String(row.cover_url || row.image_url || "").trim(), video_url: videoUrl, time_slot: `${today} 21:58`, status: "draft", telegram_message_id: "", content_key: contentId } });
});

